with ins as (insert into public.artist_external_ids (artist_slug,scheme,value,url,confidence,evidence) select x.s,x.k,x.v,x.u,'medium','sourced research 2026-11-03' from json_to_recordset('[{"s":"okedo","k":"bandcamp","v":"https://okedo.bandcamp.com/","u":"https://okedo.bandcamp.com/"}]'::json) as x(s text,k text,v text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,scheme) do nothing returning 1) select count(*) from ins;